import java.util.*; import org.springframework.data.jpa.repository.JpaRepository; import uk.ac.ravensbourne.casevault.domain.CaseRecord;
public interface CaseRepository extends JpaRepository<CaseRecord,UUID> { Optional<CaseRecord> findByIdAndOrganisationId(UUID id, UUID organisationId); List<CaseRecord> findByOrganisationIdAndOwnerAnalystId(UUID organisationId, UUID ownerAnalystId); @org.springframework.data.jpa.repository.Query("select count(a)>0 from CaseAssignment a where a.caseRecord.id=:caseId and a.analyst.id=:analystId") boolean existsAssignment(@org.springframework.data.repository.query.Param("caseId") UUID caseId,@org.springframework.data.repository.query.Param("analystId") UUID analystId); @org.springframework.data.jpa.repository.Query("select c from CaseRecord c where c.organisation.id=:org and (:q is null or lower(c.title) like :q escape '\\' or lower(c.description) like :q escape '\\') and (:category is null or c.category=:category) and (:severity is null or c.severity=:severity) and (:status is null or c.status=:status) and (:owner is null or c.ownerAnalyst.id=:owner)") org.springframework.data.domain.Page<CaseRecord> searchClient(@org.springframework.data.repository.query.Param("org") UUID org,@org.springframework.data.repository.query.Param("q") String q,@org.springframework.data.repository.query.Param("category") uk.ac.ravensbourne.casevault.domain.Category category,@org.springframework.data.repository.query.Param("severity") uk.ac.ravensbourne.casevault.domain.Severity severity,@org.springframework.data.repository.query.Param("status") uk.ac.ravensbourne.casevault.domain.CaseStatus status,@org.springframework.data.repository.query.Param("owner") UUID owner,org.springframework.data.domain.Pageable page); @org.springframework.data.jpa.repository.Query("select c from CaseRecord c where exists (select a from CaseAssignment a where a.caseRecord=c and a.analyst.id=:analyst) and (:q is null or lower(c.title) like :q escape '\\' or lower(c.description) like :q escape '\\')") org.springframework.data.domain.Page<CaseRecord> searchAssigned(@org.springframework.data.repository.query.Param("analyst") UUID analyst,@org.springframework.data.repository.query.Param("q") String q,org.springframework.data.domain.Pageable page); }
